import Foundation

/// Pasteboard types that mark data as sensitive/transient (nspasteboard.org conventions, used by 1Password,
/// Keychain, password fields, etc.). Kopi never records a change that carries any of these.
public enum PasteboardRules {
    public static let concealedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "com.apple.is-remote-clipboard.concealed",
        "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type",
        "com.typeit4me.clipping",
        "net.antelle.keeweb",
    ]

    /// Our own marker so Kopi doesn't re-record what it just wrote.
    public static let ownMarker = "com.melvern.kopi.own"

    public static func shouldIgnore(types: [String], sourceBundle: String?, ignoredBundles: Set<String>, ignoreConcealed: Bool) -> Bool {
        if types.contains(ownMarker) { return true }
        if ignoreConcealed, types.contains(where: { concealedTypes.contains($0) }) { return true }
        if let b = sourceBundle, ignoredBundles.contains(b) { return true }
        return false
    }

    /// Apps excluded out of the box — password managers.
    public static let defaultIgnored: [String] = [
        "com.agilebits.onepassword7", "com.1password.1password", "com.bitwarden.desktop",
        "com.apple.keychainaccess", "com.apple.Passwords", "in.sinew.Enpass-Desktop", "com.lastpass.LastPass",
    ]
}

/// Global hotkey descriptor (Carbon key code + Cocoa modifier flags raw value). Pure data so it's testable.
public struct HotKeySpec: Codable, Equatable, Sendable {
    public var keyCode: UInt32
    public var modifiers: UInt   // NSEvent.ModifierFlags raw value (device-independent bits only)

    public init(keyCode: UInt32, modifiers: UInt) { self.keyCode = keyCode; self.modifiers = modifiers }

    // NSEvent.ModifierFlags bits
    public static let shift: UInt = 1 << 17, control: UInt = 1 << 18, option: UInt = 1 << 19, command: UInt = 1 << 20

    /// CopyClip 2's defaults: ⌃Space opens the panel, ⌃⌥Space opens the pop-up menu at the cursor.
    public static let defaultPanel = HotKeySpec(keyCode: 49, modifiers: control)
    public static let defaultMenu = HotKeySpec(keyCode: 49, modifiers: control | option)

    public var display: String {
        var s = ""
        if modifiers & Self.control != 0 { s += "⌃" }
        if modifiers & Self.option != 0 { s += "⌥" }
        if modifiers & Self.shift != 0 { s += "⇧" }
        if modifiers & Self.command != 0 { s += "⌘" }
        return s + Self.keyName(keyCode)
    }

    public static func keyName(_ code: UInt32) -> String {
        let names: [UInt32: String] = [
            49: "Space", 36: "↩", 48: "⇥", 51: "⌫", 53: "⎋", 123: "←", 124: "→", 125: "↓", 126: "↑",
            0: "A", 11: "B", 8: "C", 2: "D", 14: "E", 3: "F", 5: "G", 4: "H", 34: "I", 38: "J", 40: "K", 37: "L", 46: "M",
            45: "N", 31: "O", 35: "P", 12: "Q", 15: "R", 1: "S", 17: "T", 32: "U", 9: "V", 13: "W", 7: "X", 16: "Y", 6: "Z",
            18: "1", 19: "2", 20: "3", 21: "4", 23: "5", 22: "6", 26: "7", 28: "8", 25: "9", 29: "0",
            27: "-", 24: "=", 33: "[", 30: "]", 41: ";", 39: "'", 43: ",", 47: ".", 44: "/", 42: "\\", 50: "`",
            122: "F1", 120: "F2", 99: "F3", 118: "F4", 96: "F5", 97: "F6", 98: "F7", 100: "F8", 101: "F9", 109: "F10", 103: "F11", 111: "F12",
        ]
        return names[code] ?? "#\(code)"
    }
}
